public class MakeDeclaredNamesUnique_enterScope_TriageGen0Test {

    private MakeDeclaredNamesUnique makeDeclaredNamesUnique;
    private NodeTraversal mockTraversal;
    private Renamer mockRootRenamer;
    private Stack<Renamer> nameStack;

    // Mocking Renamer interface/class as it is used in the logic
    interface Renamer {
        void addDeclaredName(String name);
        Renamer forChildScope();
    }

    // Mocking ContextualRenamer as per the precondition check
    interface ContextualRenamer extends Renamer {}

    @Before
    public void setUp() throws Exception {
        makeDeclaredNamesUnique = new MakeDeclaredNamesUnique();
        mockTraversal = mock(NodeTraversal.class);
        mockRootRenamer = mock(Renamer.class);

        // Use reflection to inject private fields for testing purposes
        java.lang.reflect.Field rootRenamerField = MakeDeclaredNamesUnique.class.getDeclaredField("rootRenamer");
        rootRenamerField.setAccessible(true);
        rootRenamerField.setSet(makeDeclaredNamesUnique, mockRootRenamer);

        java.lang.reflect.Field nameStackField = MakeDeclaredNamesUnique.class.getDeclaredField("nameStack");
        nameStackField.setAccessible(true);
        nameStack = (Stack<Renamer>) nameStackField.get(makeDeclaredNamesUnique);
    }

    @Test
    public void testEnterScope_EmptyStack_GlobalScope_NotFunction() {
        Node root = createNode(Token.BLOCK);
        when(mockTraversal.getScopeRoot()).thenReturn(root);
        when(mockTraversal.inGlobalScope()).thenReturn(true);

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        assertTrue(nameStack.contains(mockRootRenamer));
    }

    @Test
    public void testEnterScope_EmptyStack_NotGlobalScope_ThrowsException() {
        Node root = createNode(Token.BLOCK);
        when(mockTraversal.getScopeRoot()).thenReturn(root);
        when(mockTraversal.inGlobalScope()).thenReturn(false);

        try {
            makeDeclaredNamesUnique.enterScope(mockTraversal);
            org.junit.Assert.fail("Should have thrown Preconditions exception");
        } catch (IllegalStateException e) {
            // Expected
        }
    }

    @Test
    public void testEnterScope_EmptyStack_Function_WithContextualRenamer_ThrowsException() throws Exception {
        ContextualRenamer contextualRenamer = mock(ContextualRenamer.class);
        java.lang.reflect.Field rootRenamerField = MakeDeclaredNamesUnique.class.getDeclaredField("rootRenamer");
        rootRenamerField.setAccessible(true);
        rootRenamerField.set(makeDeclaredNamesUnique, contextualRenamer);

        Node functionNode = createNode(Token.FUNCTION);
        when(mockTraversal.getScopeRoot()).thenReturn(functionNode);
        when(mockTraversal.inGlobalScope()).thenReturn(true);

        try {
            makeDeclaredNamesUnique.enterScope(mockTraversal);
            org.junit.Assert.fail("Should have thrown Preconditions exception");
        } catch (IllegalStateException e) {
            // Expected
        }
    }

    @Test
    public void testEnterScope_EmptyStack_Function_WithStandardRenamer() {
        // Setup Function Node: FUNCTION -> (PARAMS -> [param1, param2]) -> (BLOCK -> body)
        Node functionNode = createNode(Token.FUNCTION);
        Node params = createNode(Token.PARAMS);
        Node param1 = createNode(Token.NAME);
        param1.setString("p1");
        Node param2 = createNode(Token.NAME);
        param2.setString("p2");
        params.addChild(param1);
        params.addChild(param2);

        Node block = createNode(Token.BLOCK);
        Node body = createNode(Token.EXPRESSION);
        body.setString("doSomething()");
        block.addChild(body);

        functionNode.addChild(params);
        functionNode.addChild(block);

        when(mockTraversal.getScopeRoot()).thenReturn(functionNode);
        when(mockTraversal.inGlobalScope()).thenReturn(true);

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        // Verify params were added to renamer
        // Note: The logic iterates: declarationRoot.getFirstChild().getNext().getFirstChild()
        // For FUNCTION: 1st child is PARAMS, 2nd is BLOCK. 
        // The loop starts at params.getFirstChild().getNext().getFirstChild(). 
        // This depends heavily on the specific AST structure expected by the code.
    }

    @Test
    public void testEnterScope_WithExistingStack_ChildScope() {
        Renamer parentRenamer = mock(Renamer.class);
        Renamer childRenamer = mock(Renamer.class);
        when(parentRenamer.forChildScope()).thenReturn(childRenamer);
        nameStack.push(parentRenamer);

        Node blockNode = createNode(Token.BLOCK);
        when(mockTraversal.getScopeRoot()).thenReturn(blockNode);

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        assertTrue(nameStack.contains(childRenamer));
    }

    @Test
    public void testEnterScope_NonFunctionNode_AddsDeclarations() {
        Renamer childRenamer = mock(Renamer.class);
        nameStack.push(childRenamer);

        Node blockNode = createNode(Token.BLOCK);
        Node varNode = createNode(Token.VAR);
        Node nameNode = createNode(Token.NAME);
        nameNode.setString("myVar");
        varNode.addChild(nameNode);
        blockNode.addChild(varNode);

        when(mockTraversal.getScopeRoot()).thenReturn(blockNode);

        makeDeclaredNamesUnique.enterScope(mockTraversal);

        // Verification of findDeclaredNames logic would happen here via mock interactions
    }
}
